from sage.all_cmdline import *   # import sage library

_sage_const_80 = Integer(80); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_5 = Integer(5); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_60 = Integer(60); _sage_const_0 = Integer(0); _sage_const_10 = Integer(10); _sage_const_15 = Integer(15); _sage_const_20 = Integer(20)
from ore_algebra import *
from ore_algebra import guess

R = PolynomialRing(QQ, names=('n',)); (n,) = R._first_ngens(1)
A = OreAlgebra(R, names=('Sn',)); (Sn,) = A._first_ngens(1)

# Inner sum WITHOUT C(2n,n)
inner = []
for nn in range(_sage_const_80 ):
    inner.append(sum(binomial(nn,k)**_sage_const_2  * binomial(nn+k,nn) * binomial(nn+_sage_const_2 *k,nn) for k in range(nn+_sage_const_1 )))

print("Inner sum (no C(2n,n)):", inner[:_sage_const_5 ])
L_inner = guess(inner, A)
print(f"Inner: order={L_inner.order()}, degree={max(c.degree() for c in L_inner.list())}")
print(f"  L_inner = {L_inner}")

# Full AESZ = C(2n,n) * inner
aesz = [binomial(_sage_const_2 *nn, nn) * inner[nn] for nn in range(_sage_const_80 )]
print("\nFull AESZ:", aesz[:_sage_const_5 ])

# Try to guess with explicit order/degree bounds
for ord in [_sage_const_3 , _sage_const_4 , _sage_const_5 ]:
    try:
        L_full = guess(aesz, A, order=ord)
        deg = max(c.degree() for c in L_full.list())
        print(f"  order={ord}: found! degree={deg}")
        if ord == _sage_const_3 :
            print(f"  L = {L_full}")
        break
    except Exception as e:
        print(f"  order={ord}: {str(e)[:_sage_const_60 ]}")

# Check if L_inner right-divides L_full
print("\nDoes L_inner relate to the full operator?")
# Gauge: a_n = C(2n,n) * b_n, C(2(n+1),n+1)/C(2n,n) = 4(2n+1)/(n+1)
# So Sn * v_n = g(n) * v_n where g(n) = [4(2n+1)/(n+1)]
# The gauged operator of L_inner acting on a_n is:
# L_gauged(n) = L_inner with Sn -> g(n) * Sn
# Actually: if b_n = a_n / C(2n,n), then L_inner · b = 0
# And a_n = C(2n,n) · b_n
# So L_gauged · a = 0 where L_gauged = gauge of L_inner by C(2n,n)

# Verify: what operator does guess find for the inner sum at order 3?
