print(f"  Trailing factored: {tc.factor()}")

# Check Poincaré polynomial: leading coefficients of all terms
print(f"\n  Poincaré check:")
for i, c in enumerate(L_inner.list()):
    lead = c.leading_coefficient()
    print(f"    Sn^{i}: leading coeff = {lead}")

# The Poincaré polynomial should be Σ lead_i * μ^i
leads = [c.leading_coefficient() for c in L_inner.list()]
P_poincare = sum(leads[i] * var('mu')**i for i in range(len(leads)))
print(f"\n  Poincaré(μ) = {P_poincare}")

# Solve
from sage.all import solve as solve_eq
mu = var('mu')
print(f"  Roots: {solve_eq(P_poincare, mu)}")

